AudioInput identifies an audio payload used for transcription.

type AudioInput struct {
	// FilePath is either a real filesystem path or a synthetic filename used when
	// Reader is provided.
	FilePath string
	// Reader provides the audio bytes when the input does not come from a local file.
	Reader io.Reader
}

ContentPart is a single piece of content within a message — either text or an image.

type ContentPart struct {
	// Type identifies the kind of content.
	Type ContentType
	// Text holds the text content when Type is ContentTypeText.
	Text string
	// ImageURL holds the image URL when Type is ContentTypeImageURL.
	ImageURL string
	// ImageBase64 holds the base64-encoded image bytes when Type is ContentTypeImageBase64.
	ImageBase64 string
	// MIMEType is the MIME type of the image (e.g. "image/png"

FunctionCall holds the name and JSON-encoded arguments of a tool invocation.

type FunctionCall struct {
	// Name is the name of the tool being called.
	Name string
	// Arguments is the raw JSON-encoded argument object.
	Arguments string
}

LLM is the minimal interface implemented by chat-model backends.

Implementations are expected to accept a list of messages and return the next
assistant message. Tools can be configured via WithTools.

type LLM interface {
	Execute(context.Context, []Message, []*Tool) (*Result, error)
}

Message is a single turn in a conversation between a user, assistant, or tool.

type Message struct {
	// Role is the participant role: one of RoleSystem, RoleUser, RoleAssistant, RoleTool.
	Role string
	// Parts holds the multimodal content of the message.
	// For simple text messages this will be a single ContentPart with Type ContentTypeText.
	Parts []ContentPart
	// ToolCalls holds tool invocations requested by the assistant.
	// Only populated on assistant messages.
	ToolCalls []ToolCall
	/

Pricing holds per-million-token costs for a model, expressed in US dollars.

Rates are best-effort defaults and may drift as providers change prices; use
RegisterPricing to override them or to add models not in the default table.

type Pricing struct {
	// InputPer1M is the cost in USD per 1,000,000 (uncached) input tokens.
	InputPer1M float64
	// OutputPer1M is the cost in USD per 1,000,000 output tokens.
	OutputPer1M float64
	// CacheReadPer1M is the cost in USD per 1,000,000 input tokens read

Result represents the output of an LLM execution, including the assistant message and any tool calls.

type Result struct {
	Message *Message
	// Usage holds token counts for this call. May be nil when the provider does
	// not return usage information.
	Usage *Usage
	// Model is the model that produced this result, as reported by the provider
	// (which may be more specific than the requested name, e.g. a dated version).
	// Used for best-effort cost estimation; may be empty.
	Model string
}

SchemaExpectedMapError is returned when schema normalization expects a JSON
object (map[string]any) but receives a different type.

type SchemaExpectedMapError struct {
	Got  any
	Path []string
}

SchemaNonDictionaryWhileResolvingRefError is returned when resolving a $ref
encounters a non-map value while walking the path.

type SchemaNonDictionaryWhileResolvingRefError struct {
	Ref      string
	Resolved any
}

SchemaNonStringRefError is returned when a schema contains a $ref value that
is not a string.

type SchemaNonStringRefError struct {
	RawRef any
}

SchemaUnexpectedRefFormatError is returned when a schema $ref does not use a
supported format.

type SchemaUnexpectedRefFormatError struct {
	Ref string
}

SpeechRequest describes a text-to-speech request.

type SpeechRequest struct {
	// Model optionally overrides the provider's default speech model.
	Model string
	// Input is the text to synthesize.
	Input string
	// Voice chooses the provider voice when supported.
	Voice string
	// Instructions provides optional style guidance when supported.
	Instructions string
	// Format chooses the output audio encoding.
	Format SpeechResponseFormat
	// Speed adjusts the speaking speed when supported.
	Speed

SpeechResult is the normalized output of a speech synthesis request.

type SpeechResult struct {
	// Data holds the synthesized audio bytes.
	Data []byte
	// MIMEType identifies the encoding of Data.
	MIMEType string
	// Format identifies the audio encoding used for Data.
	Format SpeechResponseFormat
}

SpeechSynthesizer is implemented by providers that support text-to-speech.

type SpeechSynthesizer interface {
	// SynthesizeSpeech converts text to spoken audio.
	SynthesizeSpeech(context.Context, SpeechRequest) (*SpeechResult, error)
}

StreamChunk is one incremental piece of a streaming LLM response.

Consumers typically accumulate TextDelta (and ReasoningDelta) for live display,
then read the complete assembled Message, Usage, and Model from the terminal
chunk (the one with Done == true).

type StreamChunk struct {
	// TextDelta is an incremental piece of assistant text. Empty on non-text chunks.
	TextDelta string
	// ReasoningDelta is an incremental piece of extended-thinking text. Empty on non-reasoning chunks.
	ReasoningDe

StreamingLLM is implemented by chat-model backends that can stream their
response incrementally, in addition to the buffered Execute.

type StreamingLLM interface {
	LLM
	// ExecuteStream returns an iterator over response chunks. The final chunk has
	// Done == true and carries the complete Message, Usage, and Model. If the
	// stream fails, the iterator yields a non-nil error and stops.
	ExecuteStream(ctx context.Context, messages []Message, tools []*Tool) iter.Seq2[StreamChunk, error]
}

Tool is a Tool that wraps a function.

type Tool struct {
	// contains filtered or unexported fields
}

ToolArgumentParseError is returned when parsing tool arguments from JSON fails.

type ToolArgumentParseError struct {
	Err error
}

ToolCall represents a single tool invocation requested by the model.

type ToolCall struct {
	// ID is the opaque identifier assigned by the model to correlate this call with its result.
	ID string
	// Type is the tool type (always ToolTypeFunction for function tools).
	Type string
	// Function holds the name and arguments for this call.
	Function FunctionCall
}

ToolNilInputTypeError is returned when a tool's input type parameter has a nil zero value.

type ToolNilInputTypeError struct {
	ToolName string
}

ToolSchemaStrictnessError is returned when ensuring strictness of a tool's JSON schema fails.

type ToolSchemaStrictnessError struct {
	Err error
}

ToolSchemaTransformError is returned when transforming a jsonschema.Schema to a map fails.

type ToolSchemaTransformError struct {
	Err error
}

Transcriber is implemented by providers that support speech-to-text.

type Transcriber interface {
	// Transcribe converts spoken audio to text.
	Transcribe(context.Context, TranscriptionRequest) (*TranscriptionResult, error)
}

TranscriptionRequest describes an audio-to-text request.

type TranscriptionRequest struct {
	// Model optionally overrides the provider's default transcription model.
	Model string
	// Input identifies the audio payload to transcribe.
	Input AudioInput
	// Prompt provides optional context that can bias transcription.
	Prompt string
	// Temperature controls output randomness when supported by the provider.
	Temperature float32
	// Language hints the spoken language using an ISO-639-1 code when s

TranscriptionResult is the normalized output of an audio transcription request.

type TranscriptionResult struct {
	// Task is the provider-reported task type.
	Task string
	// Language is the detected or enforced language code.
	Language string
	// Duration is the input audio duration in seconds when available.
	Duration float64
	// Segments holds verbose segment-level timing when requested and supported.
	Segments []TranscriptionSegment
	// Words holds verbose word-level timing when requested

TranscriptionSegment contains a timed segment in a verbose transcription result.

type TranscriptionSegment struct {
	// ID is the provider-assigned segment identifier.
	ID int
	// Seek is the provider-specific offset used internally during decoding.
	Seek int
	// Start is the segment start time in seconds.
	Start float64
	// End is the segment end time in seconds.
	End float64
	// Text is the transcript text for the segment.
	Text string
	// Tokens are provider-specific token IDs when available

TranscriptionWord contains a timed word in a verbose transcription result.

type TranscriptionWord struct {
	// Word is the recognized word.
	Word string
	// Start is the word start time in seconds.
	Start float64
	// End is the word end time in seconds.
	End float64
}

Usage holds token consumption figures from a single LLM call.

type Usage struct {
	// InputTokens is the number of tokens in the prompt sent to the model.
	InputTokens int
	// OutputTokens is the number of tokens produced by the model.
	OutputTokens int
	// CacheReadTokens is the number of input tokens served from a prompt cache.
	// Only populated by providers that report it (e.g. Anthropic prompt caching);
	// zero otherwise. These tokens are billed at the cache-read rate.
